+  display: grid;
+  grid-template-columns: minmax(320px, 0.72fr) minmax(580px, 1.28fr);
+  border: 1px solid var(--line);
+  border-radius: 26px;
+  background: var(--panel);
+  box-shadow: 0 30px 80px rgb(44 67 74 / 8%);
