+  justify-content: center;
+  font-weight: 750;
+}
+
+.primary-button {
+  width: 100%;
+  height: 52px;
+  border-radius: 12px;
+  background: var(--ink);
+  color: white;
+  gap: 10px;
+}
+
+.primary-button span {
+  font-size: 20px;
+}
+
+.primary-button:disabled,
+.download-button:disabled {
+  cursor: wait;
+  opacity: 0.6;
+}
+
+.status-message {
+  margin-top: 15px;
+  padding: 11px 12px;
+  border-radius: 9px;
+  background: #f5f7f5;
