+  display: flex;
+  gap: 9px;
+  font-size: 12px;
+  line-height: 1.45;
+}
+
+.status-message.error {
+  background: #fff2ef;
+  color: #90483d;
+}
+
+.status-message.success {
+  background: #eff7ec;
+  color: #496a40;
+}
+
+.status-dot {
+  width: 7px;
+  height: 7px;
+  margin-top: 5px;
+  border-radius: 50%;
+  background: currentColor;
+  flex: 0 0 auto;
+}
+
+.divider {
+  height: 1px;
+  margin: 31px 0 9px;
+  background: var(--line);
+}
+
+.editor-toggle {
+  width: 100%;
