+  font-size: 12px;
+  line-height: 1.5;
+}
+
+.field-row {
+  display: grid;
+  grid-template-columns: 1fr 1fr;
+  gap: 12px;
+}
+
+.upload-button {
+  min-height: 44px;
+  padding: 0 15px;
+  border: 1px dashed #aebcbe;
+  border-radius: 10px;
+  cursor: pointer;
