+
+  .site-header {
+    min-height: 68px;
+    grid-template-columns: 1fr auto;
+  }
+
+  .surface-tabs {
+    display: none;
+  }
+
+  .prototype-label {
+    font-size: 9px;
+  }
+
+  .hero {
+    width: min(100% - 32px, 980px);
+    margin: 55px auto 45px;
+  }
+
+  .hero h1 {
+    font-size: 44px;
+  }
+
+  .hero-copy {
+    font-size: 16px;
+  }
+
+  .studio-grid {
+    border-radius: 18px;
+  }
+
+  .control-panel,
+  .preview-panel {
+    padding: 25px 20px;
+  }
+
+  .preview-actions,
+  footer {
+    align-items: stretch;
+    flex-direction: column;
+  }
+
+  .download-button {
+    width: 100%;
+  }
+
+  footer {
+    padding: 25px 0;
+  }
+}
