@@ -0,0 +1,726 @@
+:root {
+  --ink: #111719;
+  --muted: #617076;
+  --line: #dbe2e2;
+  --paper: #f7f8f5;
+  --blue: #56add8;
+  --blue-dark: #317fa5;
+  --green: #dcecbc;
+  --panel: #ffffff;
+}
+
+* {
+  box-sizing: border-box;
+}
+
+html {
+  scroll-behavior: smooth;
+}
+
+body {
+  margin: 0;
+  color: var(--ink);
+  background: var(--paper);
+  font-family: Arial, Helvetica, sans-serif;
+  -webkit-font-smoothing: antialiased;
+}
+
+button,
+input,
+textarea {
+  font: inherit;
+}
+
+button {
+  color: inherit;
+}
+
+.site-header {
+  width: min(1440px, calc(100% - 64px));
+  min-height: 78px;
+  margin: 0 auto;
+  border-bottom: 1px solid var(--line);
+  display: grid;
+  grid-template-columns: 1fr auto 1fr;
+  align-items: center;
+}
+
+.wordmark {
+  color: var(--ink);
+  text-decoration: none;
+  font-size: 14px;
+  font-weight: 800;
+  letter-spacing: 0.12em;
+}
+
+.wordmark span {
+  color: var(--blue-dark);
+}
+
+.surface-tabs {
+  padding: 5px;
+  border: 1px solid var(--line);
+  border-radius: 999px;
+  background: #eef1ef;
+  display: flex;
+  gap: 4px;
+}
+
+.surface-tab {
+  padding: 9px 18px;
+  border-radius: 999px;
+  font-size: 13px;
+  font-weight: 700;
+}
+
+.surface-tab.active {
+  background: white;
+  box-shadow: 0 1px 5px rgb(24 42 48 / 10%);
+}
+
+.surface-tab.upcoming {
+  color: #8a969a;
+}
+
+.surface-tab small {
+  margin-left: 3px;
+  font-size: 9px;
+  letter-spacing: 0.08em;
+  text-transform: uppercase;
+}
+
+.prototype-label {
+  justify-self: end;
+  color: var(--muted);
+  font-size: 12px;
+  letter-spacing: 0.08em;
