    89	function deriveHeadline(tags: string[] = []) {
    90	  const normalized = tags.map((tag) => tag.toLowerCase());
    91	  const hasHydration = normalized.some((tag) =>
    92	    ["hydration", "moisturization"].includes(tag),
    93	  );
    94	  const hasRepair = normalized.some((tag) => tag.includes("repair"));
    95	  const hasSunCare = normalized.some((tag) => tag.includes("sun"));
    96	  const hasOilBalance = normalized.some((tag) => tag.includes("oil"));
    97	
    98	  if (hasHydration && hasRepair) return "Lightweight hydration.\nBarrier care.";
    99	  if (hasSunCare) return "Everyday sun protection.";
   100	  if (hasOilBalance) return "Targeted care for oily skin.";
   101	  if (hasHydration) return "Hydration for every day.";
   102	  return "Ingredient-led care.\nMade transparent.";
   103	}
