   111	function extractBadges(html: string) {
   112	  const supportedLabels = [
   113	    "Fragrance Free",
   114	    "Non-comedogenic",
   115	    "Essential Oil Free",
   116	    "Silicone Free",
   117	    "Sulphate Free",
   118	  ];
   119	  const found = supportedLabels.filter((label) =>
   120	    html.toLowerCase().includes(label.toLowerCase()),
   121	  );
   122	  return found.slice(0, 2).join(" · ");
   123	}
