   125	function shortenCopy(description: string) {
   126	  const firstSentence = description.split(/(?<=[.!?])\s/)[0] ?? description;
   127	  if (firstSentence.length <= 145) return firstSentence;
   128	  return `${firstSentence.slice(0, 141).trimEnd()}…`;
   129	}
