   131	function normalizeImageUrl(value: string) {
   132	  const url = new URL(value.startsWith("//") ? `https:${value}` : value);
   133	  if (url.hostname !== "cdn.shopify.com") {
   134	    throw new Error("The product image did not come from the expected store CDN.");
   135	  }
   136	  url.searchParams.set("width", "1000");
   137	  return url.toString();
   138	}
