   140	export async function fetchProductCreative(inputUrl: string): Promise<ProductCreative> {
   141	  const { canonicalUrl, handle } = parseMinimalistProductUrl(inputUrl);
   142	  const headers = { "User-Agent": "MinimalistAdStudio/0.1" };
   143	  const [productResponse, pageResponse] = await Promise.all([
   144	    fetch(`https://beminimalist.co/products/${handle}.js`, {
   145	      headers,
   146	      next: { revalidate: 3600 },
   147	    }),
   148	    fetch(canonicalUrl, { headers, next: { revalidate: 3600 } }).catch(() => null),
   149	  ]);
   150	
   151	  if (!productResponse.ok) {
   152	    throw new Error("Minimalist did not return product data for this URL.");
   153	  }
   154	
   155	  const product = (await productResponse.json()) as ShopifyProduct;
   156	  const pageHtml = pageResponse?.ok ? await pageResponse.text() : "";
   157	  const selectedVariant =
   158	    product.variants?.find((variant) => variant.available) ?? product.variants?.[0];
   159	  const rawImage =
   160	    selectedVariant?.featured_image?.src ?? product.featured_image ?? product.images?.[0];
   161	
   162	  if (!rawImage) throw new Error("No usable product image was found.");
   163	
   164	  const description = extractMetaDescription(pageHtml);
   165	  const fallbackCopy = `${product.title}, presented with its ingredient concentration clearly stated.`;
   166	
   167	  return {
   168	    sourceUrl: canonicalUrl,
   169	    title: product.title,
   170	    eyebrow: deriveEyebrow(product.title),
   171	    headline: deriveHeadline(product.tags),
   172	    supportingCopy: shortenCopy(description || fallbackCopy),
   173	    badges: extractBadges(pageHtml),
   174	    detailLine: product.title,
   175	    price: formatPrice(selectedVariant?.price ?? product.price) ?? "",
   176	    compareAtPrice: formatPrice(
   177	      selectedVariant?.compare_at_price ?? product.compare_at_price,
   178	    ),
   179	    size: selectedVariant?.title ?? "",
   180	    cta: "Explore product",
   181	    imageUrl: normalizeImageUrl(rawImage),
   182	  };
   183	}
